S = "Hakeem Force Academy"
QS = [
(S, "If a train covers 120 km per hour, how far will it cover in 18 minutes?", ["30 km", "24 km", "36 km", "40 km"], 2,
 "18 minutes is 18/60 = 0.3 hour. Distance = 120 x 0.3 = 36 km.", "Distance = speed x time, and the time must be in hours when the speed is in km per hour.", [143]),
(S, "Who was the Chief of Army Staff of Pakistan during the 1965 war with India?", ["General Ayub Khan", "General Muhammad Musa Khan", "General Yahya Khan", "General Gul Hassan Khan"], 1,
 "General Muhammad Musa Khan was Commander-in-Chief of the Pakistan Army from 1958 to 1966, which covers the 1965 war.", "He was followed as army chief by General Yahya Khan in 1966.", [467]),
(S, "Who was the Chief of Army Staff of Pakistan in 1999?", ["General Jahangir Karamat", "General Pervez Musharraf", "General Ziauddin Butt", "General Aslam Beg"], 1,
 "General Pervez Musharraf became Chief of Army Staff in October 1998 and held the post in 1999, including the Kargil conflict and the October 1999 takeover.", "He remained army chief until November 2007, and his predecessor was General Jahangir Karamat.", [469]),
(S, "Who was the Commander-in-Chief of the Pakistan Army during the 1971 war?", ["General Tikka Khan", "General Gul Hassan Khan", "General Yahya Khan", "General Zia ul Haq"], 2,
 "General Yahya Khan was army chief from 1966 and also President in 1971, when the war with India took place.", "General Gul Hassan Khan took over as army chief on 20 December 1971.", [468]),
(S, "Which two soldiers received the Nishan-e-Haider for bravery in the 1999 Kargil conflict?", ["Havaldar Lalak Jan and Captain Karnal Sher Khan", "Major Raja Aziz Bhatti and Major Tufail", "Sawar Muhammad Hussain and Major Shabbir Sharif", "Lance Naik Muhammad Mahfuz and Major Akram"], 0,
 "Havaldar Lalak Jan (Northern Light Infantry) and Captain Karnal Sher Khan (27 Sindh) were awarded the Nishan-e-Haider for Kargil 1999.", "Karnal Sher Khan was a Captain at the time of his martyrdom and was promoted to Colonel after death.", [476]),
(S, "On which date was the second constitution of Pakistan (the 1962 Constitution) enforced?", ["23 March 1962", "8 June 1962", "1 March 1962", "14 August 1962"], 1,
 "The 1962 Constitution, given by President Ayub Khan, came into force on 8 June 1962 and ended martial law.", "The first constitution of Pakistan was the 1956 Constitution.", [220]),
(S, "Who persuaded Hazrat Usman (RA) to accept Islam?", ["Hazrat Umar (RA)", "Hazrat Ali (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Talha (RA)"], 2,
 "Hazrat Abu Bakr (RA) presented Islam to Hazrat Usman (RA), who then accepted it at an early stage of the Prophet's mission.", "Hazrat Usman (RA) is known as Zun-Noorain because he married two daughters of the Prophet (PBUH).", [454]),
(S, "Which instrument is used to measure the altitude (angle above the horizon) of the sun?", ["Sextant", "Barometer", "Hygrometer", "Anemometer"], 0,
 "A sextant measures the angle between the horizon and a celestial body such as the sun, which gives its altitude.", "Sailors use the sextant for navigation by finding their latitude.", [406]),
(S, "Articles (a, an, the) are used mainly before which part of speech?", ["Verb", "Noun", "Adverb", "Conjunction"], 1,
 "An article is a word that comes before a noun (or its adjective) to show whether it is specific or general.", "The word the is the definite article, while a and an are indefinite articles.", [99, 100]),
(S, "Near which city did the plane crash that killed General Zia ul Haq in 1988 take place?", ["Rawalpindi", "Multan", "Bahawalpur", "Sargodha"], 2,
 "General Zia ul Haq died on 17 August 1988 when his aircraft crashed shortly after take-off near Bahawalpur.", "US Ambassador Arnold Raphel and several Pakistani generals also died in the crash.", [391]),
(S, "What is the touching or kissing of the Hajr-e-Aswad (Black Stone) during Tawaf called?", ["Sa'i", "Istilam", "Ramy", "Wuquf"], 1,
 "Istilam means touching or kissing the Black Stone, or pointing towards it when the crowd is too large.", "Tawaf is the circling of the Kaaba seven times.", [270]),
(S, "Who is the author of the play Hamlet?", ["Charles Dickens", "Christopher Marlowe", "John Milton", "William Shakespeare"], 3,
 "Hamlet is a tragedy written by William Shakespeare around 1600.", "Other famous tragedies by Shakespeare are Macbeth, Othello and King Lear.", [446]),
(S, "In which year did Quaid-e-Azam Muhammad Ali Jinnah present the Delhi Proposals?", ["1916", "1927", "1929", "1930"], 1,
 "The Delhi Muslim Proposals were put forward by Jinnah in March 1927 as a way to settle Hindu-Muslim differences on the constitution.", "The year 1916 is that of the Lucknow Pact, and the 14 Points came in 1929.", [165]),
(S, "In which ghazwa (battle campaign) did the Muslims return to Madinah without any fighting?", ["Ghazwa Badr", "Ghazwa Uhad", "Ghazwa Khandaq", "Ghazwa Tabuk"], 3,
 "In Ghazwa Tabuk (9 AH) the Byzantine army withdrew, so the Muslim army returned to Madinah without a battle.", "Tabuk was the last ghazwa led by the Prophet (PBUH) himself.", [153, 154]),
(S, "Who became the first woman Chief Justice of a High Court in Pakistan (Balochistan High Court, 2018)?", ["Justice Ashraf Jahan", "Justice Syeda Tahira Safdar", "Justice Majida Rizvi", "Justice Nasira Javed Iqbal"], 1,
 "Justice Syeda Tahira Safdar took oath as Chief Justice of the Balochistan High Court on 1 September 2018, the first woman to hold such a post in Pakistan.", "She was also the first woman civil judge in Balochistan.", [87]),
(S, "In which city is the cemetery Jannat ul Baqi located?", ["Makkah", "Madinah", "Jeddah", "Taif"], 1,
 "Jannat ul Baqi is the main cemetery of Madinah, close to the Prophet's Mosque.", "Many family members and Companions of the Prophet (PBUH) are buried there.", [352]),
(S, "How many players are there in a baseball team on the field?", ["11", "9", "7", "10"], 1,
 "A baseball team puts nine players on the field at a time.", "Cricket and football teams have 11 players each.", [130]),
(S, "What was the currency of France before the Euro?", ["Mark", "Lira", "Franc", "Peseta"], 2,
 "France used the French franc until it was replaced by the Euro (notes and coins from 2002).", "The mark was the German currency and the lira was the Italian currency before the Euro.", [54]),
(S, "What is the date of birth of the Holy Prophet Muhammad (PBUH) in the Gregorian calendar, as commonly given in Pakistani textbooks?", ["12 April 570 AD", "22 April 571 AD", "20 June 569 AD", "2 May 572 AD"], 1,
 "Pakistani textbooks commonly give 22 April 571 AD, in the Year of the Elephant, as the birth date.", "Sources differ slightly, with some giving 20 April 571 AD, and the Islamic date is 12 Rabi ul Awwal in the commonly followed view.", [250]),
(S, "Sofia is the capital of which country?", ["Serbia", "Romania", "Bulgaria", "Croatia"], 2,
 "Sofia is the largest city and capital of Bulgaria.", "Bulgaria is a Balkan country on the Black Sea.", [207]),
(S, "What is the capital of Haiti?", ["Port-au-Prince", "Kingston", "Havana", "Santo Domingo"], 0,
 "Port-au-Prince is the capital and largest city of Haiti.", "Haiti shares the island of Hispaniola with the Dominican Republic, whose capital is Santo Domingo.", [251]),
(S, "What is the capital of the Netherlands (Holland)?", ["Rotterdam", "Brussels", "The Hague", "Amsterdam"], 3,
 "Amsterdam is the constitutional capital of the Netherlands.", "The Dutch government and the royal residence are at The Hague.", [253]),
(S, "What is the capital of Honduras?", ["Managua", "Tegucigalpa", "San Salvador", "Guatemala City"], 1,
 "Tegucigalpa is the capital of Honduras.", "Managua is the capital of Nicaragua.", [254]),
(S, "What is the capital of Qatar?", ["Doha", "Manama", "Muscat", "Abu Dhabi"], 0,
 "Doha is the capital and largest city of Qatar.", "Qatar hosted the FIFA World Cup in 2022.", [256]),
(S, "What is the capital of Sierra Leone?", ["Monrovia", "Accra", "Conakry", "Freetown"], 3,
 "Freetown is the capital and largest city of Sierra Leone.", "Monrovia is the capital of neighbouring Liberia.", [38]),
(S, "On which date was the Iran-Pakistan gas pipeline agreement signed in 2010?", ["16 March 2010", "16 March 2009", "23 March 2010", "5 June 2010"], 0,
 "Iran and Pakistan signed the gas pipeline agreement on 16 March 2010.", "A formal gas export contract followed in June 2010, and Pakistan's section was inaugurated in March 2013.", [196]),
]
